    "text": "そこのファイルに近郊でツアーの候補地になってる山をリストアップしてあるから、そこから五つぐらいに絞り込んでもらいたいんだ。自分でも登れそうだって思えることを念頭に、コースの魅力度でね。他社の類似ツアーの資料も入ってるから、それも参考にしながらね。",
