    "unitId": "n1:task-comprehension:2019-12:3:line-6",
    "text": "最終的には、五つの候補地を専門家と企画担当全員でさらに検討して三つにするんだけど、その段階になったら、周辺のレジャースポットを調べてもらうのも山田さんにって思ってるんだ。帰りに寄れそうな温泉とか土産屋とかね。",
