    "text": "うちのパン屋、お客さんがのきさきに自転車を止めることがあるんですけど。どうしても歩道にはみ出してしまうので、近所から苦情が来てるんですよ。佐藤さんが経営なさってる喫茶店もうちと環境似てますけど、どうされてますか。",
