    "text": "ええ、まあ。ただ、そうすると、お店の雰囲気が悪くなっちゃうでしょ。だから、花や緑の植木鉢でのきさきのスペースを埋めちゃうんです。うちも隣に駐輪場ができるまではそうやってて、効果ありましたよ。",
