    "text": "ええとね、オンラインの社内ネットワーク上に会議記録っていう共有フォルダーがあるんだけど、そこに保存しておけば、各自が加筆修正するから。 今年度から経費削減で紙媒体では回覧しなくなったんだ。だから、印刷はなしで。",
