    "text": "それで、加筆修正して返信してもらって、それを反映させたものを完成版として共有フォルダーに入れるの。ちょっと手間がかかるけどね。あ、混乱しないように、未完成のものは共有フォルダーに保存しとかないでね。あっ、部長は完成したものを見るから。",
